    If impossible, return -1.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # filter out non-positive coins
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP: dp[i] = min coins for amount i
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
