def solve(matrix):
    # Empty matrix determinant defined as 1
    if not matrix:
        return 1
    n = len(matrix)
    # Use Fraction for exact arithmetic
    a = [[Fraction(matrix[i][j]) for j in range(n)] for i in range(n)]
    det = Fraction(1)
    for i in range(n):
        # Find pivot row
        pivot_row = None
        for r in range(i, n):
            if a[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            a[i], a[pivot_row] = a[pivot_row], a[i]
            det = -det
        pivot = a[i][i]
        det *= pivot
        for r in range(i+1, n):
            if a[r][i] == 0:
                continue
            factor = a[r][i] / pivot
            for c in range(i, n):
                a[r][c] -= factor * a[i][c]
    # determinant should be integer
    return det.numerator // det.denominator"}

