    """Simplify a Unix path.
    Handles both absolute and relative paths robustly.
    """
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                # pop only if last is a normal dir
                if stack[-1] != '..':
                    stack.pop()
                else:
                    # previous is '..', keep another '..' for relative paths
                    if not is_abs:
                        stack.append('..')
            else:
                # stack empty
                if not is_abs:
                    stack.append('..')
