{"task_id": "T25", "code": "def solve(matrix):
    # Determinant of square matrix, empty matrix returns 1
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    assert all(len(row) == n for row in matrix)
    # Use Gaussian elimination with fraction-free (Bareiss algorithm) to keep integer
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        # Find pivot
        if A[k][k] == 0:
            # swap with a lower row
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // (1 if k == 0 else A[k-1][k-1])
        det = pivot
    det *= A[n-1][n-1]
    return det"}

