    """Simplify a Unix path.
    Works for absolute and relative paths, and for empty input.
    """
    if not path:
        return '.'
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            if stack:
                # Pop only normal directories
                if stack[-1] != '..':
                    stack.pop()
                else:
                    # previous was '..' in a relative path, keep another '..'
                    if not is_abs:
                        stack.append('..')
            else:
                # At root for absolute, ignore; for relative keep '..'
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(p)
    if is_abs:
        return '/' + '/'.join(stack) if stack else '/'
